(ns hey99.ui
  (:require [clojure.java.io :as io] [clojure.string :as str] [game.gm.config :as cfg])
  (:import [org.jsoup Jsoup] [org.jsoup.safety Safelist]))

(defn escape-html [x]
  (-> (str (or x "")) (str/replace "&" "&amp;") (str/replace "<" "&lt;")
      (str/replace ">" "&gt;") (str/replace "\"" "&quot;") (str/replace "'" "&#39;")))
(defn safe-image-url [value]
  (when (string? value)
    (let [v (str/trim value)]
      (when (and (not (re-find #"[\\\s\p{Cntrl}]" v))
                 (or (and (str/starts-with? v "/") (not (str/starts-with? v "//")))
                     (try (let [u (java.net.URI. v)]
                            (and (= "https" (.getScheme u)) (.getHost u) (nil? (.getUserInfo u))))
                          (catch Exception _ false)))) v))))
(defn article-body [payload]
  (if (= "html" (get-in payload [:metadata :body_format]))
    (let [allow (doto (Safelist.)
                  (.addTags (into-array String ["p" "br" "h2" "h3" "strong" "em" "blockquote" "ul" "ol" "li" "a" "figure" "img" "figcaption"]))
                  (.addAttributes "a" (into-array String ["href" "title"]))
                  (.addProtocols "a" "href" (into-array String ["http" "https" "mailto"]))
                  (.addAttributes "img" (into-array String ["src" "alt" "width" "height"]))
                  (.addProtocols "img" "src" (into-array String ["https"]))
                  (.preserveRelativeLinks true))
          doc (Jsoup/parseBodyFragment (Jsoup/clean (str (:body payload)) "https://hey99.online/" allow))]
      (doseq [img (.select doc "img")]
        (if-let [src (safe-image-url (.attr img "src"))]
          (do
            (doseq [a ["width" "height"]]
              (when-not (re-matches #"[1-9][0-9]{0,3}" (.attr img a)) (.removeAttr img a)))
            (doto img (.attr "src" src) (.attr "loading" "lazy") (.attr "decoding" "async")))
          (.remove img)))
      (.prettyPrint (.outputSettings doc) false)
      (.html (.body doc)))
    (apply str (map #(str "<p>" (str/replace (escape-html %) "\n" "<br />") "</p>")
                    (str/split (str (:body payload)) #"\n\s*\n")))))
(defn featured-image [payload class-name eager?]
  (when-let [src (safe-image-url (if eager? (:featured_image payload) (or (get-in payload [:metadata :featured_image_thumbnail]) (:featured_image payload))))]
    (str "<img class=\"" class-name "\" src=\"" (escape-html src)
         "\" alt=\"" (escape-html (get-in payload [:metadata :featured_image_alt]))
         "\" width=\"1200\" height=\"800\" loading=\"" (if eager? "eager" "lazy")
         "\" decoding=\"async\"" (when eager? " fetchpriority=\"high\"") " />")))
(defn origin [] (or (not-empty (str (cfg/resolve-app-base-url))) "https://hey99.online"))
(defn response [html] {:status 200 :headers {"Content-Type" "text/html; charset=utf-8" "Cache-Control" "no-store"} :body html})
(defn asset [path mime]
  (if-let [r (io/resource (str "ui/" path))]
    {:status 200 :headers {"Content-Type" mime} :body (io/input-stream r)}
    {:status 404 :body "Not found"}))
(defn static-page [path]
  (if-let [r (io/resource (str "ui/" path))] (response (slurp r)) {:status 404 :body "Not found"}))
(defn page [title description path body]
  (let [template (slurp (io/resource "ui/economics/index.html"))
        url (escape-html (str (origin) path))]
    (response
      (-> template
          (str/replace #"(?s)<main id=\"main\">.*?</main>" (fn [_] (str "<main id=\"main\">" body "</main>")))
          (str/replace #"<title>[^<]*</title>" (fn [_] (str "<title>Hey99 — " (escape-html title) "</title>")))
          (str/replace #"(<meta\s+(?:name=\"description\"|property=\"og:description\"|name=\"twitter:description\")\s+content=\")[^\"]*" (fn [[_ prefix]] (str prefix (escape-html description))))
          (str/replace #"(<meta\s+(?:property=\"og:title\"|name=\"twitter:title\")\s+content=\")[^\"]*" (fn [[_ prefix]] (str prefix "Hey99 — " (escape-html title))))
          (str/replace #"(<link\s+rel=\"canonical\"\s+href=\")[^\"]*" (fn [[_ prefix]] (str prefix url)))
          (str/replace #"(<meta\s+property=\"og:url\"\s+content=\")[^\"]*" (fn [[_ prefix]] (str prefix url)))
          (str/replace "aria-current=\"page\"" "")
          (str/replace "../assets/" "/assets/")
          (str/replace "../styles.css" "/styles.css")
          (str/replace "../join/" "/join/")
          (str/replace "../market/" "/market/")
          (str/replace "../#opportunity" "/#opportunity")
          (str/replace "href=\"../\"" "href=\"/\"")
          (str/replace "href=\"./\"" "href=\"/economics/\"")
          ;; Keep share tags compact, matching the working homepage markup.
          (str/replace #"(?s)<meta\b[^>]*>" #(str/replace % #"\s*\n\s*" " "))))))
(defn hero [title text]
  (str "<section class=\"economics-hero\"><div class=\"wrap\"><span class=\"eyebrow\">#hey99 · Local stories</span><h1>" (escape-html title) "</h1><p class=\"economics-lede\">" (escape-html text) "</p></div></section>"))
(defn story-card [item]
  (let [p (:payload item) path (str "/stories/" (:slug item) "/")]
    (str "<article>" (when (safe-image-url (:featured_image p)) (str "<a href=\"" (escape-html path) "\">" (featured-image p "story-thumb" false) "</a>")) "<span class=\"economics-index\">" (escape-html (:author item)) "</span><h3><a href=\"" (escape-html path) "\">" (escape-html (:title p)) "</a></h3><p>" (escape-html (or (:summary p) (subs (str (:body p)) 0 (min 180 (count (str (:body p))))))) "</p><a class=\"text-link\" href=\"" (escape-html path) "\">Read the story ↗</a></article>")))
(defn stories-page [items]
  (let [items (sort-by :published-at > (filter :slug items))]
    (page "Stories from your local economy." "Meet the ideas, people and connections building Hey99. Stories worth reading and sharing." "/stories/"
      (str (hero "Good stories bring people together." "Ideas, everyday discoveries and local voices. Read something useful, then help it find the people who might appreciate it.")
           "<section class=\"section\"><div class=\"wrap\">"
           (if (seq items) (str "<div class=\"economics-grid\">" (apply str (map story-card items)) "</div>") "<h2>The first stories are taking shape.</h2><p>Want to help tell the story of your community? Bring an idea, a local discovery or a useful perspective.</p>")
           "<div class=\"hero-actions\"><a class=\"button\" href=\"/join/\">Suggest a story ↗</a><a class=\"text-link\" href=\"/studio/\">Writer’s studio ↗</a></div></div></section>"))))
(defn story-page [item]
  (let [p (:payload item) title (:title p) desc (or (not-empty (str/trim (str (:summary p)))) title)
        date (when (:published-at item) (.toString (.toLocalDate (.atZone (java.time.Instant/ofEpochMilli (long (:published-at item))) (java.time.ZoneId/of "America/Los_Angeles")))))
        html (str (hero title desc) "<section class=\"section\"><article class=\"wrap article-body\"><p class=\"article-byline\">" (if (= "guest" (:byline-kind item)) "By " "From ") (escape-html (:author item)) " · " (escape-html date) "</p>"
                  (featured-image p "story-featured" true)
                  (article-body p)
                  "<div class=\"hero-actions\"><button class=\"button\" data-share>Share this story ↗</button><a class=\"text-link\" href=\"/economics/\">How rewards work ↗</a></div><p class=\"share-note\">Personal sharing links credit your contribution. Hey99 is preparing to launch; checkout and payouts are not active.</p><hr /><h2>Find your place in the community.</h2><p>Bring your business, a connection or an idea.</p><div class=\"hero-actions\"><a class=\"button\" href=\"/join/\">Join Hey99 ↗</a><a class=\"text-link\" href=\"/stories/\">More stories ↗</a></div></article></section>")]
    (let [rendered (update (page title desc (str "/stories/" (:slug item) "/") html) :body
                           #(str/replace % "property=\"og:type\" content=\"website\""
                                           "property=\"og:type\" content=\"article\""))]
      (if-let [image (safe-image-url (:featured_image p))]
        (let [absolute (str (.resolve (java.net.URI. (str (origin) "/")) image))
              alt (get-in p [:metadata :featured_image_alt] "")
              mime (condp re-find (str/lower-case (or (.getPath (java.net.URI. absolute)) ""))
                     #"\.jpe?g$" "image/jpeg" #"\.png$" "image/png" #"\.webp$" "image/webp" nil)]
          (update rendered :body #(-> %
            (str/replace #"(<meta\s+(?:property=\"og:image\"|name=\"twitter:image\")\s+content=\")[^\"]*" (fn [[_ prefix]] (str prefix (escape-html absolute))))
            (str/replace #"(<meta\s+(?:property=\"og:image:alt\"|name=\"twitter:image:alt\")\s+content=\")[^\"]*" (fn [[_ prefix]] (str prefix (escape-html alt))))
            (str/replace #"(<meta\s+property=\"og:image:height\"\s+content=\")[^\"]*" (fn [[_ prefix]] (str prefix "800")))
            (str/replace #"<meta property=\"og:image:type\" content=\"[^\"]*\" />"
                         (str "<meta property=\"og:image:secure_url\" content=\"" (escape-html absolute) "\" />"
                              (when mime (str "<meta property=\"og:image:type\" content=\"" mime "\" />")))))))
        rendered))))
(defn workspace [title kind]
  (page title "Your connections, stories and participation in the Hey99 community." (str "/" kind "/")
    (str (hero title "Bring what you know. Help your local community grow.") "<section class=\"section\"><div class=\"wrap game-workspace\" id=\"game-workspace\" data-workspace=\"" kind "\"><p role=\"status\">Loading your place in Hey99…</p></div></section>")))
(defn not-found [] (assoc (page "This page is still undiscovered." "Explore Hey99." "/404/" (hero "Let’s find your way back." "Visit the Hey99 homepage or explore our local stories.")) :status 404))
(defn unavailable [] (assoc (page "Stories will be back shortly." "Hey99 stories are temporarily unavailable." "/stories/" (hero "We’ll be back shortly." "Stories are temporarily unavailable. Please try again in a moment.")) :status 503))
(defn privacy-page []
  (page "Privacy Policy" "How Hey99 collects, uses and protects information when you participate in our local community." "/privacy/"
    (str "<section class=\"economics-hero\"><div class=\"wrap\"><span class=\"eyebrow\">#hey99 · Our community</span><h1>Privacy Policy</h1><p class=\"economics-lede\">How Hey99 collects, uses and protects information when you participate in our local community.</p></div></section>"
         "<section class=\"section\"><article class=\"wrap article-body legal-copy\"><p class=\"legal-updated\">Last updated: October 11, 2026</p><nav aria-label=\"On this page\"><a href=\"#information\">Information we collect</a><a href=\"#use\">How we use information</a><a href=\"#browser\">Cookies and browser storage</a><a href=\"#publication\">Stories, profiles and sharing</a><a href=\"#providers\">Service providers and disclosures</a><a href=\"#retention\">Retention and security</a><a href=\"#choices\">Your choices and requests</a><a href=\"#updates\">Changes and contact</a></nav><section id=\"information\"><h2>Information we collect</h2><p>You can browse public pages without creating an account. When you sign in through Intergraph, account identifiers and the profile information available through sign-in help us connect you to your Hey99 membership. We store your chosen handle, roles and participation records.</p><p>We store information you submit, including story briefs, drafts, editorial feedback and published stories. If you apply to join through Tally, we receive the answers and contact details you provide. Sharing links can record a referral identifier, the page visited and the time of the visit. Our infrastructure may also process technical request information, such as IP addresses, to deliver and protect the service.</p></section><section id=\"use\"><h2>How we use information</h2><p>We use this information to operate accounts, manage editorial review, publish approved stories, credit sharing and referral relationships, respond to applications and support requests, maintain reliability and prevent abuse. Hey99 is currently a preview: checkout and payouts are not active, and preview activity does not create earnings.</p></section><section id=\"browser\"><h2>Cookies and browser storage</h2><p>A visitor cookie helps connect visits from personal sharing links. When you sign in and claim those visits, they can be associated with your Hey99 identity for referral credit. Browser storage holds your sign-in token, selected account and unfinished writing; temporary storage can remember the page you want to share.</p><p>You can clear cookies and browser storage in your browser settings. Doing so may sign you out, remove locally saved drafts or interrupt referral tracking. Signing out clears the stored sign-in token and selected account. Keep shared devices in mind when saving drafts.</p></section><section id=\"publication\"><h2>Stories, profiles and sharing</h2><p>Approved stories are public, with their credited byline and any images or information included in the published piece. Drafts and editorial feedback are available within the authorized publishing workflow. Avoid putting sensitive personal information in stories intended for publication.</p><p>Sharing a Hey99 link on another platform does not connect that social account to Hey99 or give us access to its private messages. The platform where you share has its own privacy practices.</p></section><section id=\"providers\"><h2>Service providers and disclosures</h2><p>Hey99 uses Intergraph for identity and participation services, Fly.io for hosting, and Tally for recruiting applications. These services process information needed to provide their functions under their own applicable terms and privacy policies. Public pages also load fonts from Google Fonts, which receives the requests needed to deliver them.</p><p>We may disclose information when required by applicable law or when reasonably necessary to protect the service, investigate misuse or protect people’s rights and safety. Links to other markets or websites are governed by those sites’ policies.</p></section><section id=\"retention\"><h2>Retention and security</h2><p>We retain information while it is needed to operate the service, maintain contribution and referral records, meet legal obligations, resolve disputes and enforce agreements. We use reasonable safeguards, but no online system can be guaranteed completely secure.</p></section><section id=\"choices\"><h2>Your choices and requests</h2><p>You can choose what to submit, sign out, and clear browser storage. To request access, correction or deletion of your information, or ask about rights available under applicable privacy law, <a href=\"/join/#application\">contact the Hey99 team through our application form</a>. Please indicate that your message concerns privacy or the Terms of Service.</p><p>We may need to verify your identity before acting on a request. Some records may need to be retained for legal, security or dispute-resolution purposes. Published material may remain in copies or shares held by others.</p></section><section id=\"updates\"><h2>Changes and contact</h2><p>We may update this policy as Hey99 develops. The date above identifies the latest version; material changes will be communicated through the service where appropriate. For questions, <a href=\"/join/#application\">contact the Hey99 team through our application form</a>. Please indicate that your message concerns privacy or the Terms of Service.</p></section></article></section>")))

(defn terms-page []
  (page "Terms of Service" "Clear expectations for sharing, creating and participating in Hey99." "/terms/"
    (str "<section class=\"economics-hero\"><div class=\"wrap\"><span class=\"eyebrow\">#hey99 · Our community</span><h1>Terms of Service</h1><p class=\"economics-lede\">Clear expectations for sharing, creating and participating in Hey99.</p></div></section>"
         "<section class=\"section\"><article class=\"wrap article-body legal-copy\"><p class=\"legal-updated\">Last updated: October 11, 2026</p><nav aria-label=\"On this page\"><a href=\"#welcome\">Using Hey99</a><a href=\"#conduct\">Respectful participation</a><a href=\"#content\">Your stories and other content</a><a href=\"#sharing\">Honest recommendations and sharing</a><a href=\"#preview\">Preview status and future commerce</a><a href=\"#availability\">Availability and account access</a><a href=\"#liability\">Responsibility and limits</a><a href=\"#updates\">Changes and contact</a></nav><section id=\"welcome\"><h2>Using Hey99</h2><p>These terms govern your use of Hey99 at hey99.online, including its stories, account tools, publishing workflow and sharing features. By using these services, you agree to these terms and acknowledge the <a href=\"/privacy/\">Privacy Policy</a>. If you participate on behalf of a business, you must have authority to do so.</p><p>Keep your sign-in credentials and access tokens secure. You are responsible for the activity you authorize through your account and for providing accurate information about yourself, your business and your contributions.</p></section><section id=\"conduct\"><h2>Respectful participation</h2><p>Use Hey99 lawfully and treat people with respect. Do not impersonate others, misrepresent offers, post unlawful or infringing material, harass people, send spam, manipulate referral activity, or attempt unauthorized access to accounts or systems. Do not disrupt the service or misuse another person’s information.</p></section><section id=\"content\"><h2>Your stories and other content</h2><p>You retain ownership of the content you submit. You give Hey99 permission to host, store, display and distribute that content as needed to operate the service and publish work you submit for publication. You must have the necessary rights to any text, images or other material you provide.</p><p>Writers submit work for editorial review; publication requires approval. Review facts, permissions and any AI-assisted output before submitting it. Approval does not transfer responsibility for your content to Hey99. We may decline, remove or restrict content that violates these terms or presents a legitimate legal or safety concern. Other people’s work may not be copied or republished without permission.</p></section><section id=\"sharing\"><h2>Honest recommendations and sharing</h2><p>Share things you believe in, without misleading people about your connection to a business or potential earnings. When using a personal sharing link, clearly disclose that you may earn from eligible purchases. Respect the rules of the platforms where you share and do not promise a guaranteed income or imply that preview activity earns rewards.</p></section><section id=\"preview\"><h2>Preview status and future commerce</h2><p>Hey99 is preparing to launch. There is no active checkout or payout service, and preview activity creates no earnings. Listings, examples and the <a href=\"/economics/\">How rewards work</a> page explain the intended experience; they are not a guarantee of sales, income or marketplace availability.</p><p>When commerce becomes available, each live offer will identify its applicable reward and transaction terms. Those terms will govern eligibility and the commissions for that offer. Any purchase, cancellation, refund or payout requirements will be provided before the relevant transaction or participation. No purchase or paid subscription is required to browse the current preview.</p></section><section id=\"availability\"><h2>Availability and account access</h2><p>Hey99 relies on third-party identity services, hosting and other infrastructure. Features may change or be temporarily unavailable, and uninterrupted or error-free operation is not guaranteed. We may restrict or suspend access to address misuse, security issues or legal requirements. Where practicable, we will explain the reason and provide a way to contact the team.</p><p>Other websites and social platforms have their own terms. Linking to them does not make Hey99 responsible for their services or content.</p></section><section id=\"liability\"><h2>Responsibility and limits</h2><p>To the fullest extent permitted by applicable law, the service is provided as available, without guarantees about outcomes or suitability for a particular purpose. Hey99 and its operators are not liable for indirect, incidental, consequential, special, exemplary or punitive damages, including lost profits, data, goodwill or business opportunities. These limits do not exclude responsibility or rights that applicable law does not allow us to exclude.</p></section><section id=\"updates\"><h2>Changes and contact</h2><p>We may update these terms as the service develops. The date above identifies the latest version; material changes will be communicated through the service where appropriate. For questions or to raise a concern about content or your account, <a href=\"/join/#application\">contact the Hey99 team through our application form</a>. Please indicate that your message concerns privacy or the Terms of Service.</p></section></article></section>")))

(defn about-page []
  (page "Meet Amit Rathore, founder of Hey99." "Meet Amit Rathore: a builder, writer and neighbor bringing his experience in commerce and publishing to a community-led local economy along Highway 99." "/about/"
    (str "<section class=\"economics-hero\"><div class=\"wrap\"><span class=\"eyebrow\">#hey99 · Meet the founder</span><h1>Hi, I’m Amit.</h1><p class=\"economics-lede\">Founder of Hey99. A builder, a writer, and a neighbor getting to know this place alongside you.</p></div></section>"
         "<section class=\"section\"><article class=\"wrap article-body founder-story\"><figure class=\"founder-portrait\"><img src=\"/assets/people/amit-rathore-v1.webp\" width=\"600\" height=\"600\" alt=\"Amit Rathore, founder of Hey99\" loading=\"eager\" decoding=\"async\" /><figcaption>Amit Rathore · Founder, Hey99</figcaption></figure>"
         "<h2>A new chapter, close to home.</h2><p>At the end of 2025, a change in life plans brought me from the Bay Area to the Highway 99 area. I’m still figuring out my longer-term plans, but the kindness I encountered here made an impression almost immediately.</p><p>I’ve come to love Ripon and Manteca, spending time between the two as I get to know the area. Perhaps I’ll settle in Ripon—there seem to be some lovely houses there! For now, I’m enjoying discovering the businesses, places and people that give both communities their character.</p><p>Hey99 grows out of that experience. I’m its founder, and I’m also one of the people I hope it will serve. I want us to build something we can feel part of: our place, our people, our economy.</p>"
         "<h2>Connecting the dots.</h2><p>I’ve spent much of my life building technology. What keeps drawing me back is what happens between people: a discovery, a conversation, an idea that becomes something useful when someone else picks it up.</p><p>At Runa, and later Staples, my work was close to commerce. When I cofounded Quintype in 2014, it was close to publishing: helping people get their stories into the world. Working across those spaces brought me to a question I’m still exploring: if someone’s story or recommendation helps create value, how can that person share in it?</p><p>That thread continued through PressCoin and, later, AwakeVC, Shoptype and Coselling.ai. The names changed, but I kept connecting the same dots: technology, people, the things we create, and the ways we help each other discover them. Intergraph is where I’m bringing those ideas together. Hey99 is a way to explore them with the people and businesses around me.</p>"
         "<h2>More room to be ourselves.</h2><p>In the age of AI, I’m interested in more than making work faster. I’m interested in what we might have more room to do: follow a curiosity, develop a craft, start something small, tell a story, or spend time on the connections that make life meaningful.</p><p>That’s what self-actualization means to me here: having more room to become ourselves and contribute in ways that feel natural. We don’t all want the same life. A good local economy should make space for different interests, abilities and ambitions.</p><p>Value co-creation sounds abstract, but we already do it. A shopkeeper offers something good. A neighbor recommends it. Someone shares a story that helps another person discover it. Each brings something, and together we make something possible.</p><p>I want technology to help us recognize those contributions and share in what they create. A side income can be part of that. So can belonging, confidence, and the feeling that what we care about has a place in our community.</p>"
         "<h2>Something we build together.</h2><p>I want a local merchant to feel just as welcome here as someone sharing a favorite recipe or recommending a shop to a friend. Each of us brings something: a business, a skill, a story, a connection, or simply an interest in the place we live.</p><p>And I want everyday people like us to have a chance to earn a side income from the commerce our contributions help inspire. No hard selling. No need to turn every conversation into a pitch. Just honest enthusiasm helping good things find their people.</p><p>I’m bringing my experience to this project, but the community will give it its character. I’d love to hear what would make Hey99 useful to you.</p>"
         "<div class=\"hero-actions\"><a class=\"button\" href=\"/join/\">Let’s build Hey99 together ↗</a><a class=\"text-link\" href=\"/stories/why-start-the-hey99-movement/\">Why start the Hey99 movement? ↗</a></div><p class=\"share-note\">Hey99 is preparing to launch. Checkout and payouts are not active, and preview activity does not create earnings.</p>"
         "<details class=\"founder-background\"><summary>More about my background</summary><p>For more of my work and writing, visit <a href=\"https://amitrathore.com/\">my personal website</a>. Background references: <a href=\"https://www.manning.com/books/clojure-in-action\">Manning’s author and book page</a>, <a href=\"https://blog.quintype.com/people/medianomy-interviews-chirdeep-shetty-ceo-quintype\">Quintype’s founding story</a>, and <a href=\"https://www.sec.gov/Archives/edgar/data/791519/000115752313005562/a50754459_ex991.htm\">Staples’ 2013 announcement</a>.</p></details></article></section>")))
